INSERT INTO categories (id, name, slug, description, icon_name, image_url, regional_hub) VALUES
(1, 'Terracotta & Clay Pottery', 'terracotta-pottery', 'Ancient earthenware and baked clay art sculpted by generational potters.', 'Pottery', 'https://images.unsplash.com/photo-1578749556568-bc2c40e68b61?auto=format&fit=crop&w=800&q=80', 'Bankura & Gorakhpur'),
(2, 'Jaipur Blue Pottery', 'blue-pottery', 'Turquoise glazed quartz-paste pottery with Mughal and Persian floral motifs.', 'Sparkles', 'https://images.unsplash.com/photo-1565193566173-7a0ee3dbe261?auto=format&fit=crop&w=800&q=80', 'Jaipur, Rajasthan'),
(3, 'Bastar Dokra Metalcraft', 'dokra-metalcraft', '4000-year-old lost-wax bell metal casting technique depicting tribal life.', 'Hammer', 'https://images.unsplash.com/photo-1610701596007-11502861dcfa?auto=format&fit=crop&w=800&q=80', 'Bastar & Kondagaon, Chhattisgarh'),
(4, 'Handloom & Banarasi Silk', 'handloom-silk', 'Exquisite pure silk weaves with zari brocade work hand-crafted on pit looms.', 'Layers', 'https://images.unsplash.com/photo-1610030469983-98e550d6193c?auto=format&fit=crop&w=800&q=80', 'Varanasi & Kanchipuram'),
(5, 'Madhubani & Folk Paintings', 'madhubani-paintings', 'Intricate geometric and mythological paintings made using natural pigments.', 'Palette', 'https://images.unsplash.com/photo-1579783900882-c0d3dad7b119?auto=format&fit=crop&w=800&q=80', 'Mithila, Bihar'),
(6, 'Wood Carving & Inlay Art', 'wood-carving', 'Fragrant rosewood and sheesham carved artifacts with brass wire inlay.', 'Boxes', 'https://images.unsplash.com/photo-1544816155-12df9643f363?auto=format&fit=crop&w=800&q=80', 'Saharanpur & Channapatna');
INSERT INTO artisans (id, name, phone, email, state, district, village, preferred_language, craft_specialty, experience_years, verified, shg_name, odop_registered, gem_seller_id, bio, avatar_url, total_sales_count, total_revenue, rating) VALUES
(1, 'Rameshwar Prajapati', '+91 9876543210', 'rameshwar.craft@gmail.com', 'Uttar Pradesh', 'Gorakhpur', 'Bhangaha', 'Hindi', 'Terracotta Sculptures & Planters', 28, TRUE, 'Ganga Maati SHG', TRUE, 'GEM-UP-2026-9921', 'Generational terracotta artist crafting traditional horse figurines, planters, and decorative earthen lamps using organic alluvial clay.', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=300&q=80', 142, 285600.00, 4.9),
(2, 'Leela Devi Kumhar', '+91 9823456781', 'leela.jaipurpottery@gmail.com', 'Rajasthan', 'Jaipur', 'Kot Jewar', 'Hindi', 'Jaipur Blue Pottery Decor & Dinnerware', 19, TRUE, 'Marudhar Mahila Sangathan', TRUE, 'GEM-RJ-2026-4412', 'Master artisan specializing in cobalt oxide floral glazes on dough made of quartz, glass, and Fuller earth with zero clay.', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=300&q=80', 218, 492000.00, 4.85),
(3, 'Somnath Baghel', '+91 9412398765', 'somnath.dokra@bastarart.org', 'Chhattisgarh', 'Bastar', 'Kondagaon', 'Hindi', 'Lost-Wax Dokra Brass Figures', 24, TRUE, 'Bastar Shilpakar Samiti', TRUE, 'GEM-CG-2026-8819', 'Tribal metalsmith casting brass and bronze sculptures using natural beeswax threads and clay moulds.', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=300&q=80', 89, 310500.00, 4.92),
(4, 'Geetha Sundaram', '+91 9711223344', 'geetha.kanchiweaves@gmail.com', 'Tamil Nadu', 'Kanchipuram', 'Pillaiyarpalayam', 'Tamil', 'Zari Border Pure Mulberry Silk Sarees', 31, TRUE, 'Kanchi Kaithari SHG', TRUE, 'GEM-TN-2026-1029', 'National award-winning weaver creating traditional temple border korvai sarees with certified silver-gilt zari.', 'https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=300&q=80', 310, 1850000.00, 4.96),
(5, 'Sunita Jha', '+91 9934120987', 'sunita.mithila@gmail.com', 'Bihar', 'Madhubani', 'Ranti', 'Hindi', 'Kachni & Bharni Style Folk Art', 16, TRUE, 'Mithila Kala Vikas SHG', TRUE, 'GEM-BR-2026-7734', 'Creates handmade paper canvases portraying Radha-Krishna folklore using bamboo twigs and rice paste extracts.', 'https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&w=300&q=80', 164, 426000.00, 4.88);
INSERT INTO products (id, artisan_id, category_id, title, slug, short_description, full_description, raw_material, dimensions, weight_kg, crafting_time_hours, cost_price, suggested_price, final_price, discount_percentage, stock_quantity, status, listed_on_gem, listed_on_ondc, listed_on_tribes_india, voice_language, voice_transcript_original, ai_enhanced_image, ai_confidence_score, view_count) VALUES
(1, 1, 1, 'Royal Bankura Hand-Carved Terracotta Horse', 'royal-bankura-terracotta-horse', 'Traditional ceremonial horse sculpture with majestic hollow arched neck and symbolic decorative ears.', 'Authentic Bankura Terracotta Horse sculpture hand-modelled on the potter wheel and finished with organic clay incision patterns. Fired in wood kilns for rich terracotta hues.', 'Alluvial Clay & Natural Ochre', '32cm x 18cm x 48cm', 3.20, 14, 450.00, 1450.00, 1299.00, 10, 15, 'PUBLISHED', TRUE, TRUE, TRUE, 'Hindi', 'यह हमारा पारंपरिक बांकुरा घोड़ा है जिसे हमने हाथ से चिकनी मिट्टी से गढ़ा है। धूप में सुखाकर भट्टी में पकाया गया है।', TRUE, 0.98, 1420),
(2, 2, 2, 'Jaipur Royal Turquoise Floral Blue Pottery Vase', 'jaipur-turquoise-blue-pottery-vase', 'Glazed cylindrical flower vase decorated with Persian cobalt floral motifs.', 'Crafted without clay using Egyptian faience technique combining powdered quartz, glass cullet, sajjimatti, and kankar. Hand-painted with cobalt oxide and copper oxide glazes.', 'Quartz Powder, Natural Glaze', '15cm x 15cm x 30cm', 1.80, 22, 620.00, 1890.00, 1650.00, 12, 8, 'PUBLISHED', TRUE, TRUE, FALSE, 'Hindi', 'यह नीले रंग का जयपुर का मशहूर पॉटरी वास है। इस पर कोबाल्ट का हाथ से बनाया गया फूल का डिजाइन है।', TRUE, 0.96, 2150),
(3, 3, 3, 'Bastar Tribal Musician Dokra Brass Statuette', 'bastar-dokra-tribal-musician', 'Antique bell metal heirloom figurine playing traditional horn trumpet.', 'Created with ancient non-ferrous lost-wax casting. The core is shaped with clay, wrapped in hand-pulled beeswax wires, coated with riverbed mud, and poured with molten brass.', 'Brass & Bronze Alloy', '12cm x 8cm x 24cm', 1.45, 36, 850.00, 2750.00, 2450.00, 10, 6, 'PUBLISHED', TRUE, TRUE, TRUE, 'Hindi', 'बस्तर की प्राचीन ढोकरा कला से बनी यह आदिवासी संगीतकार की पीतल की मूर्ति है, मोम की नक्काशी द्वारा निर्मित।', TRUE, 0.97, 1890),
(4, 4, 4, 'Royal Crimson Temple Border Kanjivaram Silk Saree', 'royal-crimson-kanjivaram-silk-saree', 'Pure mulberry silk saree with Korvai interlock border and gold zari Mayil motifs.', 'Woven on three-shuttle handlooms with heavy 3-ply silk yarn. Features contrasting ruby red body with pure gold-gilded metallic pallu depicting royal peacocks.', '100% Pure Mulberry Silk & Gold Zari', '5.5m Saree + 0.8m Blouse', 0.85, 96, 4500.00, 16800.00, 14999.00, 10, 4, 'PUBLISHED', TRUE, TRUE, FALSE, 'Tamil', 'காஞ்சிபுரம் தூய பட்டுப் புடவை. கெட்டி ஜரிகை மற்றும் மயில் டிசைனுடன் கைத்தறியில் நெய்யப்பட்டது.', TRUE, 0.99, 3420),
(5, 5, 5, 'Tree of Life Madhubani Canvas Painting', 'tree-of-life-madhubani-painting', 'Auspicious Kalpavriksha painting with peacocks, fishes, and sun motifs.', 'Painted on handmade handmade cotton-rag paper using neem twigs and natural colors derived from soot, turmeric, and indigo. Highlighting fertility and nature harmony.', 'Handmade Cotton Rag Paper & Natural Dyes', '45cm x 60cm', 0.35, 28, 550.00, 2200.00, 1890.00, 14, 10, 'PUBLISHED', TRUE, TRUE, TRUE, 'Hindi', 'मिथिला की पारंपरिक मधुबनी पेंटिंग जिसमें जीवन का वृक्ष और मोर प्राकृतिक रंगों द्वारा दर्शाए गए हैं।', TRUE, 0.95, 1780);
